+@_spi(InstalledApplicationStorage)
+public struct ScopedReadOnlyApplicationStorage: InstalledApplicationStorageServing {
+    private let namespace: String
+    private let readableKeys: Set<String>
+    private let read: @Sendable (KVGetArguments) async throws -> KVGetResponse
+
+    public init(namespace: String, readableKeys: Set<String>,
+                read: @escaping @Sendable (KVGetArguments) async throws -> KVGetResponse) throws {
+        guard readableKeys.count <= 128 else { throw CapabilityWireError.invalid("readableKeys") }
+        _ = try WireRules.string(["namespace": .string(namespace)], "namespace", rule: "identifier", maximum: 64)
+        for key in readableKeys {
+            _ = try WireRules.string(["key": .string(key)], "key", rule: "identifier", maximum: 128)
+        }
+        self.namespace = namespace
+        self.readableKeys = readableKeys
+        self.read = read
+    }
+
+    public func get(_ arguments: KVGetArguments) async throws -> KVGetResponse {
+        guard arguments.namespace.utf8.elementsEqual(namespace.utf8),
+              arguments.key.utf8.prefix(129).count <= 128,
+              arguments.key.utf8.allSatisfy({ $0 < 128 }), readableKeys.contains(arguments.key) else {
+            throw CapabilityFailure.permissionDenied
+        }
+        return try await read(arguments)
+    }
+
+    public func put(_ arguments: KVPutArguments, maximumTotalBytes: Int, maximumEntries: Int) async throws -> KVMutationResponse {
+        throw CapabilityFailure.permissionDenied
+    }
+
+    public func delete(_ arguments: KVDeleteArguments) async throws -> KVMutationResponse {
+        throw CapabilityFailure.permissionDenied
+    }
+}
