+import CryptoKit
+import Foundation
+@_spi(InstalledApplicationStorage) import MixerCapabilities
+@_spi(FeatureUIV3) import MixerGuest
+@_spi(FeatureUIV3) import MixerRuntimeIdentity
+import MixerUI
+@_spi(FeatureUIV3) @_spi(CapabilityDurableV3) import MixerUpdates
+
+private func require(_ condition: Bool, _ label: String) throws {
+    guard condition else { throw UpdateError("probe.check", label) }
+    print("PASS \(label)")
+}
+
+@MainActor private func denied<E: Error & Equatable>(_ expected: E, _ label: String,
+                                                     _ operation: @MainActor () async throws -> Void) async throws {
+    do { try await operation() }
+    catch let error as E {
+        try require(error == expected, "\(label) [\(error)]")
+        return
+    }
+    throw UpdateError("probe.allowed", label)
+}
+
+private func updateDenied(_ code: String, _ label: String,
+                          _ operation: () throws -> Void) throws {
+    do { try operation() }
+    catch let error as UpdateError {
+        try require(error.code == code, "\(label) [\(error.code)]")
+        return
+    }
+    throw UpdateError("probe.allowed", label)
+}
+
+private func object(_ data: Data) throws -> [String: CanonicalValue] {
+    let value = try StrictJSON.decode(CanonicalValue.self, from: data, maximumBytes: 131_072)
+    guard let fields = value.object else { throw UpdateError("probe.json", "Expected object") }
+    return fields
+}
+
+private func fields(_ value: CanonicalValue?) throws -> [String: CanonicalValue] {
+    guard let fields = value?.object else { throw UpdateError("probe.json", "Expected nested object") }
+    return fields
+}
+
+private func encode<T: Encodable>(_ value: T) throws -> Data {
+    let encoder = JSONEncoder()
+    encoder.outputFormatting = [.sortedKeys, .withoutEscapingSlashes]
+    return try encoder.encode(value)
+}
+
+private func fingerprint(_ descriptor: [String: CanonicalValue]) throws -> String {
+    try ReleaseVerifier.sha256(Data(CapabilityRuntimeIdentity.domain.utf8) + CanonicalValue.object(descriptor).canonicalCBOR())
+}
+
+private actor StorageReads {
+    var calls = 0
+    func read(_ arguments: KVGetArguments) -> KVGetResponse {
+        calls += 1
+        return KVGetResponse(found: true, valueBase64: Data(arguments.key.utf8).base64EncodedString())
+    }
+}
+
+@main struct Probe {
+    @MainActor static func main() async {
+        do {
+            try await run()
+        } catch {
+            FileHandle.standardError.write(Data("FAIL \(error)\n".utf8))
+            exit(1)
+        }
+    }
+
+    @MainActor private static func run() async throws {
+        guard CommandLine.arguments.count == 2 else {
+            throw UpdateError("probe.usage", "Pass the retained public/android directory")
+        }
+        let root = URL(fileURLWithPath: CommandLine.arguments[1], isDirectory: true)
+        func read(_ file: String) throws -> Data { try Data(contentsOf: root.appendingPathComponent(file)) }
+
+        let rawIdentity = try read("identity.json")
+        let historicalHost = try StrictJSON.decode(InstalledRuntime.self, from: read("host.json"), maximumBytes: 65_536)
+        let historicalRoots = try read("roots.json")
+        let payload = try read("exact/payload.wasm")
+        let historicalManifest = try read("exact/signed-manifest.json")
+        let historicalAssignment = try read("exact/assignment.json")
+        let historicalTime: UInt64 = 1_795_449_186
+        let historicalProfile = try FeatureUIV3ReadOnlyProfile(runtimeFingerprint: historicalHost.runtime,
+                                                              storageNamespace: "material_test")
+        try require(payload.count == 14_503 &&
+                    ReleaseVerifier.sha256(payload) == "fb225d5722eda20c7591a9e7bb112d560924cedf9da17106b57eeb049f94d3b9",
+                    "exact byte count and payload SHA-256")
+        try updateDenied("identity2.number", "unconfigured identity") { _ = try CapabilityRuntimeIdentity(json: rawIdentity) }
+        let decodedRoots = try StrictJSON.decode([TrustRoot].self, from: historicalRoots, maximumBytes: 65_536)
+        try updateDenied("v3.host.invalid", "unconfigured release verifier") {
+            _ = try ReleaseVerifierV3(host: historicalHost, roots: decodedRoots)
+        }
+
+        let historical = try CapabilityRuntimeIdentity(json: rawIdentity, featureUIV3: historicalProfile)
+        try require(historical.installedRuntime == historicalHost &&
+                    historical.capabilityExecution.turnMilliseconds == 50, "historical installed host and 50 ms turn")
+        let historicalVerifier = try historical.makeFeatureUIV3Verifier(trustRootsJSON: historicalRoots)
+        let historicalArtifact = try historicalVerifier.verifyArtifact(signedManifest: historicalManifest, payload: payload, now: historicalTime)
+        let historicalSelection = try historicalVerifier.verifyAssignment(signedAssignment: historicalAssignment,
+            artifact: historicalArtifact, channel: "beta", installation: "feature-ui-v3-probe", lastSequence: 1, now: historicalTime)
+        try require(historicalSelection.sequence == 2, "historical signed artifact and assignment")
+
+        // The installed descriptor also pins the root-file digest. Change that
+        // digest and runtime together when substituting an ephemeral signer.
+        let key = Curve25519.Signing.PrivateKey()
+        let keyID = "ephemeral-ui3-signer"
+        let roots = try encode([TrustRoot(keyID: keyID, publicKey: key.publicKey.rawRepresentation,
+            scope: historicalHost.scope, artifact: true, assignment: true)])
+        var descriptor = try object(rawIdentity)
+        var build = try fields(descriptor["build"])
+        build["trust_roots_sha256"] = .text(ReleaseVerifier.sha256(roots))
+        descriptor["build"] = .object(build)
+        let newFingerprint = try fingerprint(descriptor)
+        let reboundProfile = try FeatureUIV3ReadOnlyProfile(runtimeFingerprint: newFingerprint, storageNamespace: "material_test")
+        let rawRebound = try encode(CanonicalValue.object(descriptor))
+        try updateDenied("identity2.feature_ui_profile", "foreign descriptor fingerprint") {
+            _ = try CapabilityRuntimeIdentity(json: rawRebound, featureUIV3: historicalProfile)
+        }
+        let wrongNamespace = try FeatureUIV3ReadOnlyProfile(runtimeFingerprint: newFingerprint, storageNamespace: "different")
+        try updateDenied("identity2.feature_ui_profile", "configured namespace differs from installed grant digest") {
+            _ = try CapabilityRuntimeIdentity(json: rawRebound, featureUIV3: wrongNamespace)
+        }
+        let rebound = try CapabilityRuntimeIdentity(json: rawRebound, featureUIV3: reboundProfile)
+        try updateDenied("identity2.trust_roots_digest", "foreign root-file digest") {
+            _ = try rebound.makeFeatureUIV3Verifier(trustRootsJSON: historicalRoots)
+        }
+        let verifier = try rebound.makeFeatureUIV3Verifier(trustRootsJSON: roots)
+
+        for (section, field, value, code): (String, String, CanonicalValue, String) in [
+            ("execution", "startup_export", .text("mixer_guest_ui_start_v1"), "identity2.feature_ui_profile"),
+            ("engine", "ui_contract_sha256", .text(CapabilityRuntimeIdentity.uiContractSHA256), "identity2.contract"),
+            ("capability_execution", "turn_milliseconds", .uint(51), "identity2.number"),
+        ] {
+            var invalid = descriptor
+            var nested = try fields(descriptor[section])
+            nested[field] = value
+            invalid[section] = .object(nested)
+            let impostorProfile = try FeatureUIV3ReadOnlyProfile(runtimeFingerprint: fingerprint(invalid), storageNamespace: "material_test")
+            try updateDenied(code, "incompatible descriptor \(field) with matching fingerprint") {
+                _ = try CapabilityRuntimeIdentity(json: encode(CanonicalValue.object(invalid)), featureUIV3: impostorProfile)
+            }
+        }
+
+        func signed(_ field: String, _ values: [String: CanonicalValue]) throws -> Data {
+            let value = CanonicalValue.object(values)
+            let signature = try key.signature(for: Data("mixer.\(field == "manifest" ? "artifact" : field).v3\0".utf8) + value.canonicalCBOR())
+            return try encode(CanonicalValue.object([field: value, "signature": .text(signature.base64EncodedString())]))
+        }
+
+        var manifest = try fields(object(historicalManifest)["manifest"])
+        manifest["runtime"] = .text(newFingerprint)
+        manifest["key_id"] = .text(keyID)
+        let signedManifest = try signed("manifest", manifest)
+        let artifact = try verifier.verifyArtifact(signedManifest: signedManifest, payload: payload, now: historicalTime)
+        var assignment = try fields(object(historicalAssignment)["assignment"])
+        assignment["runtime"] = .text(newFingerprint)
+        assignment["artifact_sha256"] = .text(artifact.artifactSHA256)
+        assignment["key_id"] = .text(keyID)
+        let signedAssignment = try signed("assignment", assignment)
+        let selection = try verifier.verifyAssignment(signedAssignment: signedAssignment,
+            artifact: artifact, channel: "beta", installation: "feature-ui-v3-probe", lastSequence: 1, now: historicalTime)
+        try require(selection.sequence == 2 && artifact.payloadBytes == 14_503, "ephemeral signed artifact and assignment")
+        let offer = try verifier._authorizeOfferV3(exactManifest: signedManifest, exactAssignment: signedAssignment,
+            channel: "beta", installation: "feature-ui-v3-probe", lastSequence: 1, now: historicalTime)
+        try require(offer.sequence == 2 && offer.artifactSHA256 == artifact.artifactSHA256, "durable offer shares configured verifier checks")
+        assignment["runtime"] = .text(historicalHost.runtime)
+        try updateDenied("v3.assignment.binding", "correctly signed foreign assignment") {
+            _ = try verifier.verifyAssignment(signedAssignment: signed("assignment", assignment),
+                artifact: artifact, channel: "beta", installation: "feature-ui-v3-probe", lastSequence: 1, now: historicalTime)
+        }
+        for (field, value, code): (String, CanonicalValue, String) in [
+            ("runtime", .text(historicalHost.runtime), "v3.manifest.compatibility"),
+            ("ui_schema", .uint(1), "v3.manifest.version"),
+        ] {
