+        entry["namespaces"] = .array([.text("different"), .text("material_test")])
+        grants["entries"] = .array([.object(entry)])
+        manifest["capability_grants"] = .object(grants)
+        try updateDenied("v3.manifest.grants", "correctly signed extra storage scope") {
