+
+        let codec = FeatureDocumentV3(textValuePolicy: .standard)
+        func document(extraActions: [UIActionBinding] = []) -> UIDocument {
+            UIDocument(revision: 1, root: UINode(id: "title", kind: .textField,
+                properties: ["label": .string("Title"), "value": .string("Draft")],
+                actions: [UIActionBinding(id: "change", event: .textChange)] + extraActions))
+        }
+        let encoded = try codec.encode(document())
+        try require(try codec.decode(encoded).document == document(), "FeatureDocumentV3 text change round trip")
