+                  text.utf8.allSatisfy({ (33...126).contains($0) }),
+                  previous.map({ $0.utf8.lexicographicallyPrecedes(text.utf8) }) ?? true else {
+                throw V3Rules.error("manifest.grants", "Grant strings must be sorted unique ASCII")
+            }
