+#if MIXER_FEATURE_UI_V3
+import FieldLogStorage
+import Foundation
+import MixerCapabilities
+@_spi(FeatureUIV3) import MixerCapabilityActivation
+@_spi(FeatureUIV3) import MixerRuntimeIdentity
+@_spi(FeatureUIV3) import MixerUpdates
+
+enum InstalledPendingChanges {
+    static let bundleID = "dev.mixer.fieldlog"
+    static let scope = UpdateScope(organization: "mixer-local", project: "fieldlog",
+                                   app: "fieldlog", environment: "development", platform: "ios")
+    static let namespace = "material_test"
+
+    static func open(material: URL, workspace: URL, repository: WorkspaceRepository,
+                     installedBundleID: String) async throws -> CapabilityGuestUIRuntime {
+        guard installedBundleID == bundleID, await repository.ownsDirectory(workspace) else {
+            throw CapabilityFailure.permissionDenied
+        }
+        let pin = try read("runtime.txt", in: material, limit: 65)
+        let profile = try FeatureUIV3ReadOnlyProfile(
+            runtimeFingerprint: String(decoding: pin, as: UTF8.self).trimmingCharacters(in: .newlines),
+            storageNamespace: namespace)
+        let identityBytes = try read("identity.json", in: material)
+        let identity = try CapabilityRuntimeIdentity(json: identityBytes, featureUIV3: profile)
+        #if targetEnvironment(simulator) || os(macOS)
+        let platformEnvironment = "simulator"
+        #else
+        let platformEnvironment = "device"
+        #endif
+        guard identity.descriptor.object?["application"]?.object?["bundle_id"]?.text == installedBundleID,
+              identity.descriptor.object?["platform"]?.object?["environment"]?.text == platformEnvironment else {
+            throw CapabilityFailure.permissionDenied
+        }
+        let roles: [(String, CapabilityMaterialFile.Role)] = [
+            ("bridge.json", .bridgePolicy),
+            ("storage.json", .configuration(capabilityID: CapabilitySchemas.storageID)),
+            ("storage-grant.json", .installedGrant(capabilityID: CapabilitySchemas.storageID)),
+        ]
+        let execution = try InstalledCapabilityExecution(
+            identityJSON: identityBytes,
+            materials: roles.map { .init(role: $0.1, bytes: try read($0.0, in: material)) },
+            trustRootsJSON: read("roots.json", in: material),
+            privateContainer: workspace, featureUIV3: profile, ownerScope: scope,
+            readQueue: { try await queuePage(repository) })
+        return try await CapabilityGuestUIRuntime.open(
+            configuration: .init(directory: workspace.appendingPathComponent("installed-pending-changes"),
+                                 channel: "beta", installation: "fieldlog-ios-local", observationSeconds: 1),
+            execution: execution)
+    }
+
+    static func stage(in material: URL, on owner: CapabilityGuestUIRuntime) async throws {
+        let payload = try read("payload.wasm", in: material, limit: 14_503)
+        guard payload.count == 14_503,
+              ReleaseVerifier.sha256(payload) == "fb225d5722eda20c7591a9e7bb112d560924cedf9da17106b57eeb049f94d3b9" else {
+            throw CapabilityFailure.permissionDenied
+        }
+        let state = await owner.recoverySnapshot()
+        if state.acceptedSequence == 0 {
+            try await owner.beginDownload(signedManifest: read("signed-manifest.json", in: material),
+                                          signedAssignment: read("assignment.json", in: material))
+        } else if state.downloading == nil {
