#!/usr/bin/env python3
"""Derive the local release binding from the completed ordinary Xcode link."""
import hashlib
import json
from pathlib import Path
import subprocess
import sys


def digest(path):
    with path.open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def map_digest(values):
    return hashlib.sha256(json.dumps(values, sort_keys=True, separators=(",", ":")).encode()).hexdigest()


def inventory(directory):
    return {path.relative_to(directory).as_posix(): digest(path)
            for path in sorted(directory.rglob("*")) if path.is_file()}


work = Path(sys.argv[1]).resolve(strict=True)
app = work / "sim-build/Build/Products/Debug-iphonesimulator/FieldLog.app"
object_list = work / ("sim-build/Build/Intermediates.noindex/FieldLog.build/Debug-iphonesimulator/"
                      "FieldLog.build/Objects-normal/arm64/FieldLog.LinkFileList")
archive = work / "ios-lib/libmixer_vm_capability_experimental.a"
lock = work / "fieldlog/ios/FieldLog.xcodeproj/project.xcworkspace/xcshareddata/swiftpm/Package.resolved"
objects = [Path(line).resolve(strict=True) for line in object_list.read_text().splitlines()]
if not objects or len(set(objects)) != len(objects):
    raise ValueError("Expected the exact ordinary arm64 link input list")
linked = {p.relative_to(work).as_posix(): digest(p) for p in [*objects, archive, lock]}
products = {name: digest(app / name) for name in ("FieldLog", "FieldLog.debug.dylib", "Info.plist")}
sdk = Path(subprocess.check_output(["xcrun", "--sdk", "iphonesimulator", "--show-sdk-path"], text=True).strip())
compiler = Path(subprocess.check_output(["xcrun", "--find", "swift-frontend"], text=True).strip())
vm = work / "mixer/vm"
binding = {
    "build": {
        "link_inputs_sha256": map_digest({"objects": linked, "outputs": products}),
        "native_fallback_sha256": map_digest(inventory(work / "fieldlog/Sources")),
    },
    "engine": {
        "artifact_sha256": digest(archive),
        "source_sha256": map_digest({directory: inventory(vm / directory) for directory in ("src", "include")}),
    },
    "toolchain": {
        "compiler_sha256": digest(compiler),
        "compiler_version": subprocess.check_output(["swift", "--version"], text=True).strip().replace("\n", " "),
        "sdk_sha256": digest(sdk / "SDKSettings.json"),
        "sdk_version": subprocess.check_output(
            ["xcrun", "--sdk", "iphonesimulator", "--show-sdk-version"], text=True).strip(),
        "build_tools_sha256": map_digest({
            "xcode": subprocess.check_output(["xcodebuild", "-version"], text=True),
            "project": digest(lock.parents[3] / "project.pbxproj"),
        }),
    },
    "linked": linked,
    "products": products,
}
print(json.dumps(binding, indent=2, sort_keys=True))

