import Foundation
import XCTest

@MainActor
final class F10OrdinaryPendingChangesUITests: XCTestCase {
    func testExactQueueAndCachedReopen() throws {
        continueAfterFailure = false
        let app = XCUIApplication(bundleIdentifier: "dev.mixer.fieldlog")
        app.launchArguments = ["--fieldlog-ui-workspace", UUID().uuidString, "--fieldlog-f10-observation"]
        app.launch()
        defer { app.terminate() }
        tap(app.buttons["create-first-project"])
        XCTAssertTrue(app.staticTexts["test-workspace-badge"].exists)
        enter("F10 workshop", in: app.textFields["project-name"])
        tap(app.buttons["save-project"])
        XCTAssertTrue(app.navigationBars["F10 workshop"].waitForExistence(timeout: 10))
        try addTask("Measure opening", to: app)
        try addTask("Check fasteners", to: app)

        let first = try observeQueue(in: app, expectedCandidate: nil)
        tap(app.tabBars.buttons["Projects"])
        app.terminate()
        app.launch()
        let reopened = try observeQueue(in: app, expectedCandidate: first.candidate)
        XCTAssertEqual(first.workspace, reopened.workspace)
        XCTAssertNotEqual(first.launch, reopened.launch)
    }

    func testSignedDeliveryPhase() throws {
        continueAfterFailure = false
        let env = ProcessInfo.processInfo.environment
        let phase = try XCTUnwrap(env["F10_PHASE"])
        let workspace = try XCTUnwrap(env["F10_WORKSPACE"])
        XCTAssertNotNil(UUID(uuidString: workspace))
        let app = XCUIApplication(bundleIdentifier: "dev.mixer.fieldlog")
        let mode = ["exact-offline", "rollback-offline"].contains(phase) ? "offline" :
            (phase == "disabled" ? "disabled" : try XCTUnwrap(env["F10_ORIGIN_PORT"]))
        app.launchArguments = ["--fieldlog-ui-workspace", workspace, "--fieldlog-f10-observation", "--fieldlog-f10-delivery", mode]
        app.launch()
        defer { app.terminate() }
        if phase == "disabled" {
            tap(app.tabBars.buttons["On device"])
            XCTAssertFalse(app.staticTexts["fieldlog-f10-expected-health"].exists)
            XCTAssertFalse(app.buttons["workspace-on-device"].exists)
            return
        }
        if phase == "prior" {
            tap(app.buttons["create-first-project"])
            XCTAssertTrue(app.staticTexts["test-workspace-badge"].exists)
            enter("F10 workshop", in: app.textFields["project-name"])
            tap(app.buttons["save-project"])
            XCTAssertTrue(app.navigationBars["F10 workshop"].waitForExistence(timeout: 10))
            try addTask("Measure opening", to: app)
            try addTask("Check fasteners", to: app)
        }
        if phase == "exact" || phase == "exact-offline" {
            _ = try observeQueue(in: app, expectedCandidate: nil, expectedSequence: 2, cached: phase == "exact-offline")
        } else {
            XCTAssertTrue(["prior", "rollback", "rollback-offline"].contains(phase))
            tap(app.tabBars.buttons["On device"])
            XCTAssertTrue(app.buttons["workspace-entries"].waitForExistence(timeout: 15), app.debugDescription)
            _ = try observeHealth(in: app, sequence: phase == "prior" ? 1 : 3, cached: phase == "rollback-offline")
        }
        tap(app.tabBars.buttons["Projects"])
    }

    private struct Evidence: Decodable {
        let candidate: String
        let launch: String
        let sequence: Int
        let workspace: String
        let preAttachHealthy: String?
        let hydratedRevision: UInt64
        let phase: String
        let workspaceUnchanged: Bool
        let cached: Bool
    }

    private func observeHealth(in app: XCUIApplication, sequence: Int, cached: Bool) throws -> Evidence {
        let readback = app.staticTexts["fieldlog-f10-expected-health"]
        let expected = NSPredicate { object, _ in
            guard let element = object as? XCUIElement, element.exists,
                  let encoded = element.value as? String,
                  let sample = try? JSONDecoder().decode(Evidence.self, from: Data(encoded.utf8))
            else { return false }
            return sample.phase == "healthyGuest"
        }
        XCTAssertEqual(XCTWaiter.wait(for: [
            XCTNSPredicateExpectation(predicate: expected, object: readback)
        ], timeout: 15), .completed, app.debugDescription)
        let encoded = try XCTUnwrap(readback.value as? String)
        let health = try JSONDecoder().decode(Evidence.self, from: Data(encoded.utf8))
        XCTAssertEqual(health.sequence, sequence)
        XCTAssertGreaterThan(health.hydratedRevision, 1)
        XCTAssertTrue(health.workspaceUnchanged)
        XCTAssertEqual(health.cached, cached)
        if cached { XCTAssertEqual(health.preAttachHealthy, health.candidate) }
        else { XCTAssertNotEqual(health.preAttachHealthy, health.candidate) }
        let attachment = XCTAttachment(string: encoded)
        attachment.name = "ordinary-f10-sequence-\(sequence)-cached-\(cached)"
        attachment.lifetime = .keepAlways
        add(attachment)
        return health
    }

    private func observeQueue(in app: XCUIApplication, expectedCandidate: String?, expectedSequence: Int = 1,
                              cached: Bool = false) throws -> Evidence {
        tap(app.tabBars.buttons["On device"])
        let opener = app.buttons["workspace-on-device"]
        XCTAssertTrue(opener.waitForExistence(timeout: 15), app.debugDescription)
        let health = try observeHealth(in: app, sequence: expectedSequence, cached: cached || expectedCandidate != nil)
        if let expectedCandidate { XCTAssertEqual(health.candidate, expectedCandidate) }

        tap(opener)
        let new = " — Saved on device · Not sent"
        XCTAssertTrue(app.staticTexts["queue.position"].waitForExistence(timeout: 10))
        XCTAssertEqual(app.staticTexts["queue.position"].label, "Page 1 of 1 · Changes 1–3 of 3 · Newest first")
        let rows = app.staticTexts.matching(NSPredicate(format: "identifier BEGINSWITH %@", "pending."))
            .allElementsBoundByIndex
        XCTAssertEqual(Set(rows.map(\.identifier)).count, 3)
        XCTAssertEqual(rows.map(\.label), [
            "Task updated: Check fasteners" + new,
            "Task updated: Measure opening" + new,
            "Project created" + new
        ])
        XCTAssertFalse(app.buttons["queue.next"].isEnabled)
        return health
    }

    private func addTask(_ name: String, to app: XCUIApplication) throws {
        tap(app.buttons["Add task"])
        let title = app.textFields["task-title"]
        enter(name, in: title)
        tap(app.navigationBars["New task"].buttons["Add"])
        XCTAssertTrue(app.buttons[name + ", not completed"].waitForExistence(timeout: 10))
    }

    private func tap(_ element: XCUIElement) {
        XCTAssertTrue(element.waitForExistence(timeout: 12), element.debugDescription)
        element.tap()
    }

    private func enter(_ text: String, in field: XCUIElement) {
        tap(field)
        field.typeText(text)
    }
}

