+// Relay counts the actual adapter requests and supplies deliberately corrupt
+// bytes from the otherwise real Go origin. It is bound only to loopback.
+func ordinaryReplayRelay(origin string, client *http.Client, mode string) (*httptest.Server, *atomic.Int64) {
