+				} else {
+					raw[i] = 'A'
+				}
+			}
+		case mode == "tamper" && r.URL.Path != "/v3/updates":
+			raw = bytes.Replace(raw, []byte(`"payload":"AGFz`), []byte(`"payload":"BGFz`), 1)
+		}
+		w.WriteHeader(response.StatusCode)
+		_, _ = w.Write(raw)
+	}))
+	return relay, seen
