import Darwin
@testable import FieldLogAndroid
import FieldLogStorage
import Foundation
@_spi(InstalledApplicationStorage) import MixerCapabilities
@_spi(AndroidGuestUIV1) import MixerCapabilityActivation
import MixerUI
import MixerUpdates

@_silgen_name("mxish_start") private func startBridge() -> Int32
@_silgen_name("mxish_last_id") private func lastID(_ facade: UInt64, _ kind: UInt32) -> UInt64
@_silgen_name("mxish_call_entry") private func callEntry(_ facade: UInt64, _ kind: UInt32) -> Int32
@_silgen_name("mxish_live_allocations") private func allocations() -> UInt64
@_silgen_name("f10_copy_frame") private func copyFrame(
    _ facade: UInt64, _ bytes: UnsafeMutablePointer<UInt8>, _ capacity: UInt32
) -> UInt32

@_silgen_name("mxis_feature_ui_v3_event") private func nativeEvent(
    _ facade: UInt64, _ attachment: UInt64, _ token: UInt64, _ bytes: UnsafePointer<UInt8>?, _ count: UInt32
) -> Int32

@_cdecl("mxish_swift_scalar_entry")
func hostControl(_ facade: UInt64, _ kind: UInt32) -> Int32 {
    guard kind == 16, let packet = try? currentFrame(facade),
          let item = packet.identities.first(where: { $0.id == "workspace.queue" }),
          let bytes = try? JSONEncoder().encode(UIEventEnvelope(revision: packet.document.revision,
                identity: item, event: .activate)) else { return -1 }
    return bytes.withUnsafeBytes {
        nativeEvent(facade, lastID(facade, 1), lastID(facade, 2),
                    $0.bindMemory(to: UInt8.self).baseAddress, UInt32(bytes.count))
    }
}

private struct Frame: Decodable {
    struct Document: Decodable {
        struct Root: Decodable { let id: String }
        let revision: UInt64
        let root: Root
    }
    let document: Document
    let identities: [UINodeIdentity]
}

private func currentFrame(_ facade: UInt64) throws -> Frame? {
    var bytes = [UInt8](repeating: 0, count: 65_536)
    let length = copyFrame(facade, &bytes, UInt32(bytes.count))
    guard length > 0 else { return nil }
    return try JSONDecoder().decode(Frame.self, from: Data(bytes.prefix(Int(length))))
}

private func check(_ value: Bool, _ message: String) throws {
    guard value else { throw UpdateError("probe", message) }
}

private actor ReadCounter {
    private var count = 0
    func read(_ arguments: KVGetArguments) -> KVGetResponse {
        count += 1
        return .init(found: true, valueBase64: "AA==")
    }
    func total() -> Int { count }
}

enum OriginReplay {
    @MainActor static func run(_ arguments: [String]) async throws {
        let material = URL(fileURLWithPath: arguments[2], isDirectory: true)
        let root = URL(fileURLWithPath: arguments[3], isDirectory: true)
        let mode = arguments[4]
        let port = arguments[5]
        let expected = UInt64(arguments[6])!
        let artifact = arguments[7]
        let storage = root.appendingPathComponent("FieldLog", isDirectory: true)
        let workspace = storage.appendingPathComponent("workspace.json")
        let selector = root.appendingPathComponent("pending-changes-origin.txt")
        let recovery = root.appendingPathComponent("pending-changes-recovery", isDirectory: true)
        let checkpoint = recovery.appendingPathComponent("state.json")
        let baseline = try Data(contentsOf: workspace)
        if mode == "disabled" {
            try await checkGrant()
            try check(!FileManager.default.fileExists(atPath: checkpoint.path), "disabled opened a recovery store")
            try check(try Data(contentsOf: workspace) == baseline, "disabled modified workspace")
            print("PASS disabled")
            return
        }

        if mode == "offline" {
            if FileManager.default.fileExists(atPath: selector.path) { try FileManager.default.removeItem(at: selector) }
        } else {
            try Data("\(port)\n".utf8).write(to: selector, options: .atomic)
        }
        let delivery = try InstalledPendingChanges.Delivery.selected(in: root)
        try check(startBridge() == 0, "Android host bridge did not install")
        let repository = try WorkspaceRepository(directory: storage)
        let execution = try InstalledPendingChanges.execution(material: material, root: root,
            bundleID: InstalledPendingChanges.bundleID, repository: repository)
        let installation = "2df49400-f31a-4ac7-b344-382e6ec30cf7"
        let owner = try await CapabilityGuestUIAndroidRuntime.open(
            configuration: .init(directory: recovery, channel: InstalledPendingChanges.channel,
                                 installation: installation, observationSeconds: 1),
            execution: execution)
        var offlineBaseline: Data?
        do {
            let before = owner.recoverySnapshot()
            let beforeBytes = try Data(contentsOf: checkpoint)
            let expectsRefusal = ["wrong-scope", "tamper", "signature"].contains(mode)
            do {
                try await InstalledPendingChanges.acquire(material: material, bundleID: InstalledPendingChanges.bundleID,
                    installation: installation, delivery: delivery, owner: owner)
                try check(!expectsRefusal, "invalid response reached the store")
            } catch {
                guard expectsRefusal, (error as? UpdateError)?.code != "probe" else { throw error }
                print("refused \(mode) \(error)")
            }
            let after = owner.recoverySnapshot()
            try check(after.acceptedSequence == expected, "unexpected high-water sequence \(after.acceptedSequence)")
            try check(after.healthy == before.healthy, "acquisition granted frame health")
            if mode == "live" {
                try check(after.staged != nil && after.downloading == nil, "live release was not fully staged")
                let state = try checkpointObject(checkpoint)
                let candidates = state["candidates"] as? [String: [String: Any]]
                let candidate = candidates?[after.staged ?? ""]
                try check(candidate?["artifactSHA256"] as? String == artifact, "staged artifact differed from the signed origin offer")
            } else {
                try check(try Data(contentsOf: checkpoint) == beforeBytes, "acquisition changed checkpoint")
            }
            if expected >= 2 {
                try checkCachedPayloads(in: recovery)
                print("cache contains 2002- and 14503-byte payloads at sequence=\(expected)")
            }
            if mode == "live" || mode == "offline" {
                async let started = owner.start()
                let inert = try await frame(owner.facade, revision: 1)
                try check(inert.document.root.id == "f10.loading", "missing inert loading frame")
                try check(callEntry(owner.facade, 12) != 0, "wrong attachment accepted as display")
                try check(callEntry(owner.facade, 10) == 0, "inert witness refused")
                let activation = try await started
                try check(activation.phase == .provisionalGuest || activation.phase == .healthyGuest,
                          "startup \(activation.phase) \(String(describing: activation.terminalCause))")
                let opening = try await frame(owner.facade, revision: 2)
                try check(opening.identities.contains { $0.id == "workspace.queue" }, "Entries action missing")
                try check(callEntry(owner.facade, 10) == 0, "revision-2 witness refused")
                try check(callEntry(owner.facade, 16) == 0, "Entries opening action refused")
                let hydrated = try await frame(owner.facade, revision: 3)
                if expected == 2 {
                    let rows = hydrated.identities.filter { $0.id.hasPrefix("pending.") }.count
                    try check(rows == 20, "expected twenty rendered queue rows, found \(rows)")
                } else {
                    try check(hydrated.identities.contains { $0.id == "workspace.entries.destination" },
                              "predecessor Entries destination missing")
                }
                try check(owner.recoverySnapshot().healthy == before.healthy, "pre-witness frame granted health")
                try check(callEntry(owner.facade, 10) == 0, "revision-3 witness refused")
                let deadline = ContinuousClock.now + .seconds(4)
                while owner.recoverySnapshot().activation.phase != .healthyGuest && ContinuousClock.now < deadline {
                    try await Task.sleep(for: .milliseconds(10))
                }
                let healthy = owner.recoverySnapshot()
                try check(healthy.activation.phase == .healthyGuest && healthy.healthy == healthy.activation.candidateID,
                          "no witnessed health \(healthy.activation.phase)")
                if mode == "live" {
                    try check(healthy.healthy == after.staged, "different staged candidate reached health")
                }
                if mode == "offline" {
                    try check(healthy.healthy == before.healthy, "offline selected a different candidate")
                    offlineBaseline = beforeBytes
                }
                print("healthy sequence=\(expected) candidate=\(healthy.healthy ?? "-")")
            }
            try check(try Data(contentsOf: workspace) == baseline, "workspace bytes changed")
        } catch {
            let failure = owner.recoverySnapshot().activation
            let frame = try? currentFrame(owner.facade)
            print("failure activation=\(failure.phase) stop=\(String(describing: failure.terminalCause)) bridge=\(String(describing: failure.firstBridgeFailure)) ui=\(String(describing: failure.firstUIProtocolFailure)) frame=\(String(describing: frame?.document.revision)) root=\(String(describing: frame?.document.root.id))")
            let closed = await owner.close()
            await repository.close()
            print("failure cleanup closed=\(closed) allocations=\(allocations())")
            throw error
        }
        let closed = await owner.close()
        await repository.close()
        try check(closed && allocations() == 0, "Android transport did not retire")
        let terminal = owner.recoverySnapshot()
        try check(terminal.closed && !terminal.activation.cleanupPending && !terminal.incompleteAttempt,
                  "pending Android recovery or cleanup")
        if let offlineBaseline {
            let before = try normalizedCheckpoint(offlineBaseline)
            let after = try normalizedCheckpoint(Data(contentsOf: checkpoint))
            let changed = Set(before.keys).union(after.keys).filter { before[$0] != after[$0] }.sorted()
            try check(changed.isEmpty, "offline changed durable recovery fields \(changed)")
        }
        print("PASS \(mode) sequence=\(expected) closed")
    }

    private static func normalizedCheckpoint(_ bytes: Data) throws -> [String: NSObject] {
        guard var state = try JSONSerialization.jsonObject(with: bytes) as? [String: NSObject],
              var healthy = state["healthy"] as? [String: NSObject] else {
            throw UpdateError("probe", "missing durable health")
        }
        healthy.removeValue(forKey: "launchID")
        healthy.removeValue(forKey: "committedAtWallTime")
        state["healthy"] = healthy as NSDictionary
        return state
    }

    private static func checkCachedPayloads(in recovery: URL) throws {
        let names = try FileManager.default.contentsOfDirectory(atPath: recovery.path)
        let hashes = Set(try names.filter { $0.hasSuffix(".payload") }.map {
            ReleaseVerifier.sha256(try Data(contentsOf: recovery.appendingPathComponent($0)))
        })
        try check(hashes.contains(InstalledPendingChanges.priorSHA256) &&
                  hashes.contains(InstalledPendingChanges.payloadSHA256), "both Wasm payloads were not cached")
    }

    private static func checkpointObject(_ file: URL) throws -> [String: Any] {
        guard let fields = try JSONSerialization.jsonObject(with: Data(contentsOf: file)) as? [String: Any] else {
            throw UpdateError("probe", "checkpoint is not an object")
        }
        return fields
    }

    private static func frame(_ facade: UInt64, revision: UInt64) async throws -> Frame {
        let deadline = ContinuousClock.now + .seconds(3)
        while ContinuousClock.now < deadline {
            if let frame = try currentFrame(facade), frame.document.revision == revision { return frame }
            try await Task.sleep(for: .milliseconds(10))
        }
        throw UpdateError("probe", "revision \(revision) did not reach Android transport")
    }

    private static func checkGrant() async throws {
        let reads = ReadCounter()
        let service = try ScopedReadOnlyApplicationStorage(namespace: InstalledPendingChanges.namespace,
            readableKeys: ["queue-0"]) { await reads.read($0) }
        func denied(_ block: () async throws -> Void) async throws {
            do { try await block(); throw UpdateError("probe", "storage refusal missing") }
            catch CapabilityFailure.permissionDenied {}
        }
        let namespace = InstalledPendingChanges.namespace
        try await denied { _ = try await service.get(.init(namespace: "foreign", key: "queue-0")) }
        try await denied { _ = try await service.get(.init(namespace: namespace, key: "queue-1")) }
        try await denied {
            _ = try await service.put(.init(namespace: namespace, key: "queue-0", valueBase64: "AA=="),
                                      maximumTotalBytes: 10, maximumEntries: 2)
        }
        try await denied { _ = try await service.delete(.init(namespace: namespace, key: "queue-0")) }
